fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(x1.len(), x2.len(), "input vectors must have the same length");

    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let r = a & b;

        // Element-wise properties (checked at runtime):
        // 1) r equals bitwise AND of corresponding inputs
        debug_assert_eq!(r, a & b);
        // 2) commutativity on these elements
        debug_assert_eq!(a & b, b & a);
        // 3) AND with zero yields zero
        debug_assert_eq!(a & 0u8, 0u8);
        debug_assert_eq!(0u8 & b, 0u8);
        // 4) idempotence: value AND itself is itself
        debug_assert_eq!(a & a, a);
        debug_assert_eq!(b & b, b);
        // 5) result is <= each operand
        debug_assert!(r <= a);
        debug_assert!(r <= b);

        out.push(r);
    }

    out
}